import re, json, os

def parse(txt):
    nums=[[int(x) for x in r.split()] for r in txt.strip().split('\n')]
    return nums

def comps(g, cols):
    h=len(g); seen=set(); out=[]
    for r in range(h):
        for c in range(cols):
            if g[r][c] and (r,c) not in seen:
                col=g[r][c]; stack=[(r,c)]; cells=[]
                while stack:
                    a,b=stack.pop()
                    if (a,b) in seen or g[a][b]!=col: continue
                    seen.add((a,b)); cells.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<h and 0<=y<cols and (x,y) not in seen: stack.append((x,y))
                mc=sum(b for _,b in cells)/len(cells)
                out.append({'color':col,'cells':cells,'colband':0 if mc<cols/2 else 1})
    out.sort(key=lambda s:(s['colband'], min(r for r,_ in s['cells'])))
    return out

# mapping derived: color -> (length, direction)
M={1:(3,'R'),2:(2,'L'),3:(4,'L'),6:(2,'D')}

def transform(g):
    h=len(g); w=len(g[0])
    div=next(c for c in range(w) if all(g[r][c]==4 for r in range(h)))
    # marker 5 in right region
    mr=mc=None
    for r in range(h):
        for c in range(div+1,w):
            if g[r][c]==5: mr,mc=r,c-div-1
    out=[[0]* (w-div-1) for _ in range(h)]
    out[mr][mc]=5
    shapes=comps(g,div)
    pr,pc=mr,mc
    for s in shapes:
        L,d=M[s['color']]
        r,c=pr+1,pc
        for i in range(L):
            out[r][c]=s['color']
            if d=='R': c+=1
            elif d=='L': c-=1
            else: r+=1
        if d=='R': pc=c-1; pr=r
        elif d=='L': pc=c+1; pr=r
        else: pc=c; pr=r-1
        # store end
        if d=='R': end=(pr,pc)
        elif d=='L': end=(pr,pc)
        else: end=(r,c)
        pr,pc=end
    return out

