                        x,y=a+da,b+db
                        if 0<=x<h and 0<=y<div and (x,y) not in seen: stack.append((x,y))
                raw.append((col,cells))
    # group by 3x3 block: row band = min_row//4, col band = 0/1 by min_col<4
